            "市场对这份答卷反应热烈。8 月 20 日，凯莱英 A 股盘中触及涨停板 187.65 元，全天成交额 45.71 亿元、换手率 7.87%，总市值一度站上 657.85 亿元，多项数据刷新上市以来单日纪录。当日整个医药板块集体躁动，全市场 38 只医药股涨停——源头正是 8 月初药明康德超预期的半年报所点燃的 CXO 板块行情。",
