    {
        "id": "wuxi-biologics-complex-molecule-2026",
        "date": "2026-08-28",
        "company": "药明生物",
        "category": "行业观察",
        "title": "药明生物：以「复杂分子专家」定位，加速创新产业化兑现",
        "summary": "药明生物发布品牌观点长文，阐述其作为双/多抗、ADC 等复杂分子「全生命周期技术专家」的定位：2026 上半年新增综合项目 169 个（双/多抗与 ADC 占比 71%），复杂分子收入占比超 50%（同比+约 30%）；以 WuXiBody™、WuXiDARx™、WuXia™ TrueSite、WuXiUP™ 等技术矩阵，将复杂风险转化为产业化确定性。",
        "source": "药明生物官方公众号",
        "source_url": "https://mp.weixin.qq.com/s/53GaX_m52OgrU8f7JwomUQ",
        "body": [
            "过去几年，双/多特异性抗体、ADC 等复杂分子快速崛起，持续推动全球生物药创新向更高维度发展。据 Beacon Intelligence 数据，截至 2026 年 1 月，全球活跃研发中的双/多特异性药物已超过 1,700 个、抗体偶联药物（ADC）超过 1,200 个，复杂分子已成为当前生物药创新的重要驱动力。凭借 CRDMO 一体化平台与规模化经验，药明生物正成为越来越多复杂分子项目的首选合作伙伴——2026 年上半年新增综合项目 169 个，其中双/多抗与 ADC 项目占比达 71%，复杂分子项目在公司上半年收入占比超 50%、同比增长约 30%。",
            {"video": {"cover": "/assets/img/wuxi-biologics-complex-2026/video-cover.jpg", "url": "https://mp.weixin.qq.com/s/53GaX_m52OgrU8f7JwomUQ", "caption": "药明生物「复杂分子专家」品牌视频（微信原生，点击前往原文观看）"}},
            "如果说过去十余年双/多抗与 ADC 最重要的任务是证明科学价值，今天随着重磅交易涌现、项目加速进入临床后期及获批，行业正进入「复杂分子加速迈向产业化验证」的新阶段。监管端，FDA 批准的双抗从 2014 年的 1 款增至 2025 年的 15 款，ADC 领域已有 14 款获 FDA 批准上市；资本端，Pfizer 收购 Seagen、J&J 收购 Ambrx、Merck 收购 CN101 全球权益、Pfizer 与三生制药的重磅合作，均释放出同一信号：复杂分子价值已获监管与资本双重验证，竞争正从科学发现转向产业化兑现效率。",
            "这一变化的根本原因在于，复杂分子的技术风险并非孤立存在，而是沿分子设计、工艺开发、分析表征、临床生产与商业化供应持续传导。因此产业化效率不仅取决于平台是否完整，更取决于是否有专家能力贯穿全生命周期——从分子设计到细胞株开发、从工艺放大到质量分析、从临床生产到商业化供应，每一环节都影响后续路径与最终成功率。复杂分子时代真正需要的，是能将产业化思维、平台能力与规模化经验融为一体，并将每次项目实践沉淀为下一次成功基础的技术专家。",
            "产业化思维赋能源头设计。药明生物坚持将产业化思维前移，在设计阶段同步评估表达、稳定性、纯化、分析与生产需求，从源头识别并降低后续风险。以 WuXiBody™ 双抗平台为例，其通过创新结构设计解决轻重链错配问题，兼具高表达、高稳定性与易纯化，已支持超 50 项全球合作，广泛应用于 TCE 等前沿领域；公司还构建了 SDArBody™（VHH 单域抗体）、SkyBody™（工程化 scFv）、OmniFlic 公用轻链等平台，以及 WuXiDARx™（DAR 精准控制）、WuXi Payload-Linker™（创新连接子与载荷）等 ADC 技术体系。",
            "规模化项目验证经验赋能开发。细胞株开发方面，新一代定点整合 CHO 平台 WuXia™ TrueSite 实现双抗平均表达量 7.5–10 g/L、单抗 8–12 g/L，可助客户降本 30%–50%，DNA-to-MCB 仅需 9–10 周（快于行业平均 1–3 个月），自 2025 年 10 月推出已应用于 70+ 项目；另有 WuXia293™ Stable（HEK293）、EffiX™ 微生物表达平台（胞内表达最高超 20 g/L）形成优势互补。工艺端，WuXiUP™ 超强化灌流工艺将生产效率提升至传统工艺的 5–20 倍，WuXiUI™ 超高效连续工艺实现较传统补料分批 3–6 倍的生产率提升。",
            "制剂开发打通复杂分子走向患者的「最后一公里」。围绕静注（IV）向皮下注射（SC）的行业趋势，药明生物构建了一体化高剂量解决方案：WuXiHigh™ 高浓度平台支持高达 240 mg/mL 蛋白浓度，透明质酸酶共制剂平台支持大体积皮下给药，并结合自动注射器与可穿戴给药装置，持续优化从开发到患者给药的体验。",
            "系统化思维破解质量、速度、成本「不可能三角」。药明生物采用一次性生产技术（SUT）结合「横向扩展（Scale-out）」模式灵活调整规模；质量合规方面，截至 2026 年 6 月已通过 49 次全球监管检查（含 23 次 FDA 与 EMA 检查）。数字化方面，PatroLab™ 数字孪生平台可在线监测 40 余项关键工艺参数，电子批记录（EBR）与「黄金批次（Golden Batch）」机制推动生产从经验驱动走向数据驱动。",
            "行业已证明复杂分子能创造巨大创新价值，未来更关注如何以更高效率与成功率将其转化为惠及患者的产品。药明生物以 CRDMO 一体化平台、对复杂分子风险的深刻理解与经上千项目验证的体系，帮助客户降低风险、缩短周期、提升成功率——这正是越来越多全球客户选择药明生物的重要原因。",
        ],
    },
