            "这笔融资与公司年内的产能与并购节奏相互呼应。上半年康龙化成营收 75.95 亿元、同比增长 17.92%，CDMO 服务收入同比增长 32.78%，CDMO 新签订单增速突破 50%；同期公司已在绍兴追加 30 亿元投资、在杭州钱塘区签约约 20 亿元新建基地，并通过配售新 H 股取得现金折合人民币 11.85 亿元。资本工具的组合使用，为产能交付提供了资金保障，但也意味着折旧与财务费用的压力将在一段时间内延续。"
