            "制剂端，商业化吹灌封（BFS）车间、卡式瓶制剂车间、口服固体制剂车间（OSD4）预计本年内投产；商业化西林瓶车间、喷雾干燥车间（SDP2&3）预计 2027 年陆续建成投产。新增符合国内外 GMP 规范的商业化生产线，将进一步提升无菌制剂与固体制剂的临床及商业化承接与交付能力。",
            "公司同时披露，制剂订单境外占比已超过三分之一，小分子业务将聚焦肿瘤及减重领域，并将延续中性外汇管理策略、通过连续流技术及工艺优化提升客户成本优势。管理层强调，核心跟踪线是「新兴业务订单交付 + 产能爬坡速度」能否支撑公司收入加速与毛利率回升的双重预期。"
