            "合同生产将在三星生物位于韩国仁川松岛的基地进行，合同期至 2033 年 12 月 31 日。公司强调，在全球经济不确定性上升、CDMO 市场竞争加剧的背景下，拿下这份将持续生产与供应至 2033 年的长期合同具有特别意义，有助于锁定稳定的订单积压、强化中长期收入基础。",
