    {
        "id": "nobel-physics-2026",
        "date": "2026-10-06",
        "company": "诺贝尔奖",
        "category": "行业观察",
        "title": "2026年诺贝尔物理学奖：Francis Halzen 与冰立方中微子天文台",
        "summary": "2026年诺贝尔物理学奖授予 Francis Halzen，表彰其对冰立方中微子天文台（IceCube）的决定性贡献，以及来自天体物理源的高能中微子的发现。",
        "source": "诺贝尔奖官网",
        "source_url": "https://www.nobelprize.org/prizes/physics/2026/press-release/",
        "body": [
            "2026年诺贝尔物理学奖授予美国威斯康星大学麦迪逊分校教授 Francis Halzen，以表彰其对冰立方中微子天文台（IceCube Neutrino Observatory）的决定性贡献，以及来自天体物理源的高能中微子的发现。",
            "中微子几乎无处不在，却能穿透地球与人体而几乎不留痕迹；只有在极偶然的情况下，单个中微子与原子核碰撞，才会产生可被探测的光信号。Halzen 于1988年首次提出利用南极冰层捕捉中微子的构想——在厚达约1立方千米的透明冰体中布设光学传感器，追踪来自宇宙深处的高能中微子。",
            "在他的领导下，冰立方天文台于2011年建成，随后探测到首批高能中微子，并确认其中部分来自太阳系之外。诺贝尔物理学委员会主席 Mark Pearce 评价，Halzen 的坚韧与科学远见“为一种全新的天文学铺平了道路”。",
            {
                "quote": "他的坚韧和科学远见，为一种全新的天文学铺平了道路。",
                "by": "诺贝尔物理学委员会主席 Mark Pearce"
            }
        ]
    },
