    {
        "id": "wuxi-apptec-induced-proximity-q3-2026",
        "date": "2026-10-12",
        "company": "药明康德",
        "category": "行业观察",
        "title": "治疗“癌症之王”：新型RAS抑制剂如何拓展小分子药物边界？｜2026 Q3 诱导接近药物观察",
        "summary": "2026年第三季度，FDA先后批准 BMS 的 CELMoD 疗法 iberdomide 与 Revolution Medicines 的 RAS 分子胶 daraxonrasib，非降解型诱导接近药物进入产业验证；默沙东、中外制药等交易频出，Nature / Nat Biotech 多项系统化分子胶发现方法相继发表。药明康德梳理诱导接近药物趋势，并展示其覆盖 PROTAC、分子胶、RIPTAC 等的一体化 CRDMO 平台能力。",
        "source": "药明康德微信公众号",
        "source_url": "https://mp.weixin.qq.com/s/IJvDAVIJqVRatqdMZttmVA",
        "body": [
            {
                "lead": "过去几年，诱导接近（induced proximity）主要用于将靶蛋白与 E3 泛素连接酶拉近，让疾病相关蛋白被细胞自身的蛋白降解系统“销毁”。然而，诱导接近改变的不只是蛋白的稳定性，更是分子之间的相互作用关系——药物可以让一个蛋白被降解，也可以让两个蛋白形成新的复合体，从而抑制信号传导、稳定蛋白，甚至改变其位置或功能。"
            },
            "2026 年第三季度，两款采用不同诱导接近机制的新药先后获美国 FDA 批准，显示诱导接近正迈向多种作用机制的临床转化。以 RAS 三元复合体抑制剂和非降解型分子胶为代表的新策略，展现了诱导接近在非蛋白降解领域的发展潜力。面对这些变化，药明康德依托一体化、端到端的 CRDMO 赋能平台，构建了覆盖蛋白降解靶向嵌合体（PROTAC）、分子胶、调节诱导接近靶向嵌合体（RIPTAC）等多种分子类型的能力体系。",
            {
                "h": "两款不同机制的诱导接近新药同季获 FDA 批准"
            },
            "今年 5 月，辉瑞（Pfizer）与 Arvinas 联合开发的 vepdegestrant（Veppanu）获 FDA 批准，标志着双功能蛋白降解药物完成从科学概念到上市药物的重要跨越。第三季度，诱导接近领域又迎来两个监管里程碑。",
            "8 月 13 日，FDA 加速批准百时美施贵宝（BMS）的 iberdomide（Zenbexus）——它与 E3 泛素连接酶复合体的底物识别蛋白 cereblon（CRBN）结合，促进转录因子 Aiolos 和 Ikaros 被募集、泛素化并降解；BMS 称这是其首款获批的 CRBN E3 连接酶调节剂（CELMoD）疗法。8 月 26 日，Revolution Medicines 的 daraxonrasib（Rasonque）获 FDA 批准，用于转移性胰腺腺癌；它与伴侣蛋白 cyclophilin A（CypA）结合形成二元复合物，再结合活化态 RAS 形成三元复合体，以空间位阻阻断 RAS 与下游效应蛋白的相互作用——并不把 RAS 送入蛋白酶体。",
            {
                "h": "非降解型诱导接近加速进入产业验证"
            },
            "如果说蛋白降解是诱导接近最成熟的方向之一，那么 2026 年第三季度，非降解型诱导接近开始形成清晰的临床进展与产业化信号。上述 daraxonrasib 即是最直接的例子：借助 CypA 诱导形成 RAS-药物-CypA 三元复合体，用空间位阻阻止 RAS 与下游效应蛋白结合。",
            "这一思路正向更多 RAS/MAPK 通路药物延伸。9 月 28 日，默沙东（MSD）与思璞锐（SciBrunch Therapeutics）达成全球独家许可，获得口服 KRAS G12D（ON）分子胶抑制剂 SPR2015，思璞锐将获 4 亿美元首付款，交易潜在总额最高达 21.3 亿美元。仅一天后，中外制药（Chugai）宣布与 InxMed 达成全球许可，将 RAF-MEK 分子胶 SPYK04 的全球权益授予 InxMed——它同时结合 RAF 和 MEK，将两者“黏合”成失活复合体，阻断肿瘤生长信号。",
            "在肿瘤学之外，非降解型分子胶也开始进入其他疾病领域。Enveda 开发的口服小分子 ENV-294 是一种非降解型分子胶，通过稳定一个此前未被药物靶向的免疫相关蛋白发挥作用，其中重度特应性皮炎 1b 期临床已获积极结果，目前正开展多项 2 期研究。这些项目共同提示，诱导接近正从“促进蛋白降解”进一步拓展至“通过调节蛋白相互作用改变蛋白功能”。",
            {
                "quote": "药物除了直接结合靶蛋白上的特定口袋，还可以利用新的分子相互作用改变靶点的命运或功能。",
                "by": "药明康德《2026 Q3 诱导接近药物观察》"
            },
            {
                "h": "从理性设计到系统化发现，研发工具箱进一步扩展"
            },
            "分子胶的发现曾很大程度上依赖偶然。随着 CRBN 等 E3 连接酶机制被解析，研究者已能更有目的地优化分子胶。本季度多项研究进一步拓展了探索方向：8 月发表于 Nature 的一项研究开发基于多重质谱的分子胶筛选方法，将 7 种 E3 连接酶与 5,000 个小分子组合筛选，发现了能重新编程 E3 连接酶 DCAF11 的分子 M12——它需经谷胱甘肽 S-转移酶介导的谷胱甘肽化后才形成活性分子胶，募集 RNA 解旋酶 DDX18 并促进其降解。",
            "另一项 8 月发表于 Nature Biotechnology 的研究，把搜索对象扩大到了蛋白组尺度的“潜在相互作用空间”：利用 GluePCA 分析 CRBN-泊马度胺复合体可募集的蛋白，发现约 210 种锌指蛋白结构域能与之相互作用；再结合 AI 蛋白表面分析工具 MaSIF-mimicry，在蛋白组尺度识别出 6 种已知和 43 种此前未知的 CRBN-泊马度胺结合蛋白。与此同时，8 月在线发表于 ACS Chemical Biology 的 PhenoDEL 方法，将 DNA 编码化合物库与单细胞光流控结合，直接读取细胞内蛋白降解表型。思路正在变化：从优化已知分子走向系统搜索新 E3，从寻找已知底物走向绘制潜在相互作用网络，从检测结合走向直接筛选细胞功能表型。",
            {
                "h": "一体化平台助力诱导接近药物开发"
            },
            "在靶向蛋白降解疗法十余年的产业转化中，药明康德几乎全程参与。针对分子胶早期发现低命中率的挑战，药明康德采取“双轨并进”策略：一方面通过多样化 DNA 编码化合物库（DEL）大范围探索化学空间，另一方面借助聚焦化合物库精细化研究已知蛋白体系。在筛选技术上，其亲和筛选质谱（ASMS）构建了涵盖超过 37 万个小分子的广谱化合物库，通过比较单蛋白与双蛋白条件下的质谱信号差异筛选分子胶候选物；高通量筛选（HTS）则在“一孔一化合物”自动化模式下结合功能实验迅速锁定候选分子。",
            "如今，药明康德相关能力已涵盖 PROTAC、调节诱导接近靶向嵌合体（RIPTAC）、自噬靶向嵌合体（AUTAC）、溶酶体靶向嵌合体（LYTAC）、去泛素化酶靶向嵌合体（DUBTAC）、核糖核酸酶靶向嵌合体（RIBOTAC）、磷酸化诱导嵌合小分子（PHIC）以及抗体偶联降解剂（DAC）等主要分子类型。",
            {
                "quote": "展望未来，药明康德将持续以一体化、端到端的 CRDMO 赋能平台，助力全球合作伙伴加速创新药物的研发生产进程，让科学突破更快为患者带来福祉。",
                "by": "药明康德"
            },
            {
                "faq": [
                    {"q": "什么是诱导接近药物（induced-proximity drugs）？", "a": "一类通过让两个蛋白物理靠近而调控其功能的药物，涵盖 PROTAC（靶向蛋白降解）、分子胶、RIPTAC / LYTAC / DUBTAC / RIBOTAC 等，区别于传统占位抑制。"},
                    {"q": "2026 年第三季度有哪些监管里程碑？", "a": "FDA 于第三季度连批 BMS 的 CELMoD iberdomide 与 Revolution 的 RAS 分子胶 daraxonrasib，显示诱导接近机制进入产业验证期。"},
                    {"q": "这对 CDMO 意味着什么机会？", "a": "分子胶与 PROTAC 需要复杂的多步合成、偶联、analytical 与 CMC 能力，为 CRDMO 在高活性复杂小分子与偶联平台创造增量订单。"}
                ]
            }
        ]
    },
